<!DOCTYPE html><html><head><meta charset="UTF-8"><title>My Complaints</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:Inter,sans-serif;background:#f1f4f9;padding:20px}.card{max-width:700px;margin:0 auto;background:#fff;border-radius:14px;padding:16px;border:1px solid #eef0f4}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;border-bottom:1px solid #f3f4f6;text-align:left}</style></head><body><div class="card"><h3>My Complaints (<?php echo count($my); ?>)</h3><table><tr><th>REF</th><th>Subject</th><th>Category</th><th>Status</th><th></th></tr><?php foreach(array_reverse($my) as $c){ echo '<tr><td>CMP-'.str_pad($c['id'],6,'0',STR_PAD_LEFT).'</td><td>'.htmlspecialchars($c['subject']).'</td><td>'.$c['category'].'</td><td>'.$c['status'].'</td><td><a href="complaint_details.php?id='.$c['id'].'" style="color:#4f46e5;text-decoration:none;font-weight:600">View</a></td></tr>'; } ?></table><div style="margin-top:12px"><a href="dashboard.php" style="font-size:12px;color:#4f46e5;text-decoration:none">← Back</a></div></div></body></html>
